    revisionChecklist: ["Explain name binding, identity, equality, mutability, aliasing, shallow copy, and call-by-sharing.", "Trace LEGB lookup, closure cells, late binding, decorators, and nonlocal/global behavior.", "Use iteration, context-manager, callable, comparison, hash, and descriptor protocols deliberately.", "Distinguish iterable, iterator, generator function, generator object, comprehension, and generator expression.", "Explain exception propagation, chaining, finally, context cleanup, and narrow recovery boundaries.", "Diagnose imports through package context, sys.path, sys.modules, metadata, and environment selection.", "Choose threads, processes, asyncio, vectorization, or native code from the workload and ownership model.", "Explain the GIL without claiming application thread safety or universal lack of parallelism.", "Use pytest fixtures, property tests, debugger, profiler, tracemalloc, and task/thread dumps for distinct evidence.", "Secure serialization, queries, templates, subprocesses, paths, secrets, uploads, and dependencies."],
    questions: [
      { prompt: "Is Python pass-by-value or pass-by-reference? Demonstrate the real model.", difficulty: "easy", answer: "Python uses call-by-sharing: an object reference is passed by value. The parameter initially names the same object. Mutating that object is visible through aliases, while rebinding the parameter changes only the local name.", whyTricky: "Candidates invent separate rules for lists and integers from observed mutability.", rubric: ["States one call-by-sharing rule.", "Separates mutation from rebinding.", "Uses one mutable example."] },
      { prompt: "Why is a mutable default argument shared across calls?", difficulty: "easy", answer: "Default expressions run once when def executes, and the object is stored with the function. Each omitted argument binds to that object. Use an immutable sentinel such as None and create per-call mutable state inside.", whyTricky: "The default appears in the signature and is assumed to run at call time.", rubric: ["Names definition-time evaluation.", "Explains the shared stored object.", "Shows the sentinel pattern."] },
      { prompt: "Differentiate __getattr__, __getattribute__, properties, and descriptors.", difficulty: "hard", answer: "__getattribute__ participates in every instance lookup; __getattr__ is a fallback. property is a data descriptor. Descriptors define __get__, __set__, or __delete__ and participate in precedence with instance state and MRO; functions are descriptors that bind methods.", whyTricky: "Framework magic is memorized without the lookup order.", rubric: ["Gets always-versus-fallback right.", "Identifies property as a descriptor.", "Mentions precedence or method binding."] },
      { prompt: "What happens when a generator yields, and when is finally run?", difficulty: "hard", answer: "yield returns a value and suspends the frame with its position and locals. It resumes on next, send, or throw. finally runs on completion, exception, explicit close, or finalization, but critical resources need explicit owning contexts.", whyTricky: "Generators are described as list replacements, hiding suspended frames and cleanup lifetime.", rubric: ["Explains frame suspension.", "Names resume mechanisms.", "Connects close/finally to resource ownership."] },
      { prompt: "Why does CPU-heavy work block asyncio, and how should it be handled?", difficulty: "medium", answer: "The event loop runs task continuations until they await. CPU-heavy Python code does not yield, so timers and sockets wait. Reduce or chunk work, use processes for Python CPU tasks, or use appropriate vectorized/native code.", whyTricky: "async syntax is confused with preemptive scheduling and parallelism.", rubric: ["Explains cooperative scheduling.", "Identifies non-yielding CPU work.", "Chooses an appropriate escape path."] },
      { prompt: "Does the GIL remove the need for locks?", difficulty: "hard", answer: "No. The GIL is an interpreter mechanism, not an application invariant lock. Workflows span bytecodes, invoke user code, release during I/O/native work, and interleave between check and action. Use locks, queues, immutability, confinement, transactions, or redesign.", whyTricky: "Some built-in operations appear atomic in one CPython version and are generalized.", rubric: ["Rejects application thread-safety.", "Explains multi-step interleaving.", "Names valid alternatives."] },
      { prompt: "Why can a circular import expose a missing attribute?", difficulty: "medium", answer: "Python inserts a module in sys.modules before finishing its top-level code. In a cycle, the peer receives that partially initialized object, so names defined later are absent. Move shared contracts or reduce import-time coupling.", whyTricky: "Import is viewed as textual inclusion rather than cached execution.", rubric: ["Mentions early sys.modules insertion.", "Explains partial initialization.", "Proposes a structural remedy."] },
      { prompt: "When is shallow copy correct, and why can deepcopy be dangerous?", difficulty: "medium", answer: "Shallow copy is correct when shared children are intended or immutable. deepcopy may duplicate identity-bearing resources, explode cost, mishandle handles, or violate domain ownership. Prefer explicit domain copying of state that should diverge.", whyTricky: "Copy depth is treated as a more-is-safer setting.", rubric: ["Explains nested alias preservation.", "Names resource and identity risks.", "Recommends ownership-aware copying."] }
    ],
    flashcards: [
      { front: "Python assignment", back: "Bind a name to an object; it neither copies the object nor declares fixed value storage." },
      { front: "call-by-sharing", back: "Pass an object reference by value; mutation is shared, parameter rebinding is local." },
      { front: "Mutable default", back: "Created once when def executes; use a sentinel for per-call mutable state." },
      { front: "Iterable versus iterator", back: "An iterable creates an iterator; an iterator carries next-position state and is usually single-pass." },
      { front: "Generator", back: "An iterator backed by a suspended frame containing control position and locals." },
      { front: "Context manager", back: "Paired setup and cleanup that runs exit handling on success or exception." },
      { front: "Import cache", back: "sys.modules stores module objects, including partially initialized modules during cycles." },
      { front: "asyncio", back: "Cooperative task scheduling; progress requires non-blocking operations that await or yield." }
    ],
